120	        &self,
121	        program: &mut Program,
122	        my_ir_generator_info: &mut MyIRGeneratorInfo,
123	    ) -> Result<IRBuildResult, String> {
124	        // Declare the SysY library functions.
125	        let i32_ty = Type::get_i32();
126	        let ptr_i32_ty = Type::get_pointer(Type::get_i32());
127	        let unit_ty = Type::get_unit();
128	        let lib_funcs: Vec<(&str, Vec<Type>, Type)> = vec![
129	            ("getint", vec![], i32_ty.clone()),
130	            ("getch", vec![], i32_ty.clone()),
131	            ("getarray", vec![ptr_i32_ty.clone()], i32_ty.clone()),
132	            ("putint", vec![i32_ty.clone()], unit_ty.clone()),
133	            ("putch", vec![i32_ty.clone()], unit_ty.clone()),
134	            ("putarray", vec![i32_ty.clone(), ptr_i32_ty.clone()], unit_ty.clone()),
135	            ("starttime", vec![], unit_ty.clone()),
136	            ("stoptime", vec![], unit_ty.clone()),
137	        ];
138	        for (name, params, ret) in lib_funcs {
139	            let func_data = koopa::ir::FunctionData::new_decl(format!("@{}", name), params, ret);
140	            let func = program.new_func(func_data);
141	            my_ir_generator_info.function_table.insert(name.to_string(), func);
142	        }
143	        match self {
144	            CompUnit::Default(units) => {
145	                for unit in units {
146	                    unit.build(program, my_ir_generator_info)?;
147	                }
148	            }
149	        }
150	        Ok(IRBuildResult::OK)
151	    }
152	}
