    /// Emits `sw reg, offset(sp)`. Goes through x31 for large offsets.
    fn store_with_offset(&mut self, reg: usize, offset: isize) -> Vec<String> {
        if (MIN_SHORT_INT..=MAX_SHORT_INT).contains(&offset) {
            vec![format!(
                "  sw\t{}, {}({})",
                REGISTER_NAMES[reg], offset, REGISTER_NAMES[REG_SP]
            )]
        } else {
            vec![format!(
                "  li\t{}, {}\n  add\t{}, {}, {}\n  sw\t{}, 0({})",
                REGISTER_NAMES[REG_X31],
                offset,
                REGISTER_NAMES[REG_X31],
                REGISTER_NAMES[REG_SP],
                REGISTER_NAMES[REG_X31],
                REGISTER_NAMES[reg],
                REGISTER_NAMES[REG_X31]
            )]
        }
    }
    /// Emits `lw reg, offset(sp)`. Goes through x31 for large offsets.
    fn load_with_offset(&mut self, reg: usize, offset: isize) -> Vec<String> {
        if (MIN_SHORT_INT..=MAX_SHORT_INT).contains(&offset) {
            vec![format!(
                "  lw\t{}, {}({})",
                REGISTER_NAMES[reg], offset, REGISTER_NAMES[REG_SP]
            )]
        } else {
            vec![format!(
                "  li\t{}, {}\n  add\t{}, {}, {}\n  lw\t{}, 0({})",
                REGISTER_NAMES[REG_X31],
                offset,
                REGISTER_NAMES[REG_X31],
                REGISTER_NAMES[REG_SP],
                REGISTER_NAMES[REG_X31],
                REGISTER_NAMES[reg],
                REGISTER_NAMES[REG_X31]
            )]
        }
    }
    /// Computes `sp + offset` into `reg`. Goes through x31 for large offsets.
    fn add_with_offset(&mut self, reg: usize, offset: isize) -> Vec<String> {
        if (MIN_SHORT_INT..=MAX_SHORT_INT).contains(&offset) {
            vec![format!(
                "  addi\t{}, {}, {}",
                REGISTER_NAMES[reg], REGISTER_NAMES[REG_SP], offset
            )]
        } else {
            vec![format!(
                "  li\t{}, {}\n  add\t{}, {}, {}",
                REGISTER_NAMES[REG_X31],
                offset,
                REGISTER_NAMES[reg],
                REGISTER_NAMES[REG_SP],
                REGISTER_NAMES[REG_X31]
            )]
        }
    }
    fn load_global(&mut self, reg: usize, symbol_name: String) -> Vec<String> {
        vec![format!(
            "  la\t{}, {}\n  lw\t{}, 0({})",
            REGISTER_NAMES[REG_X31], symbol_name, REGISTER_NAMES[reg], REGISTER_NAMES[REG_X31]
        )]
    }
    fn store_global(&mut self, reg: usize, symbol_name: String) -> Vec<String> {
        vec![format!(
            "  la\t{}, {}\n  sw\t{}, 0({})",
            REGISTER_NAMES[REG_X31], symbol_name, REGISTER_NAMES[reg], REGISTER_NAMES[REG_X31]
        )]
    }

    /// Returns true for constants (which can be re-materialized, no slot needed).
    fn is_const_value(&self, value: Value) -> bool {
        match value.is_global() {
            true => self.program.borrow_value(value).kind().is_const(),
            false => self.fd.dfg().value(value).kind().is_const(),
        }
    }

    /// Registers work as a write-through cache: memory is always up to date,
    /// so at block boundaries nothing has to be written back for globals.
    fn store_global_variables(&mut self) -> Vec<String> {
        Vec::new()
    }

    /// Invalidates every cached register. Safe at block boundaries and after
    /// calls, because every value's stack slot is always up to date.
    fn store_local_variables(&mut self) -> Vec<String> {
        for reg in 0..REGISTER_NAMES.len() {
            self.__free_user(reg);
        }
        self.curr_time = 0;
        Vec::new()
    }

    /// Kick the value in a register and store it to memory.
    fn save_register(&mut self, reg: usize) -> Vec<String> {
        let mut codes = Vec::new();
        if let Some(value) = self.register_user[reg] {
            // Only temporaries need spilling; named values are write-through
            // and constants can be re-materialized with `li`.
            if self.is_temp_value(value) && !self.is_const_value(value) {
                if let Some(&offset) = self.local_value_location.get(&value) {
                    codes.extend(self.store_with_offset(reg, offset as isize));
                }
            }
        }
        self.__free_user(reg);
        codes
    }

    /// Finds a usable register.
    /// If all registers are being used, then kicks one.
    fn get_tmp_reg(&mut self) -> (usize, Vec<String>) {
        for &reg in REGISTER_FOR_TEMP.iter() {
            if self.register_user[reg].is_none() {
                return (reg, Vec::new());
            }
        }
        let mut lru = REGISTER_FOR_TEMP[0];
        for &reg in REGISTER_FOR_TEMP.iter() {
            if self.register_used_time[reg] < self.register_used_time[lru] {
                lru = reg;
            }
        }
        let codes = self.save_register(lru);
        (lru, codes)
    }

    /// Emits the code that loads the content of `value` into `reg`.
    fn __load_value(&mut self, value: Value, reg: usize) -> Vec<String> {
        let mut codes = Vec::new();
        if value.is_global() {
            let value_data = self.program.borrow_value(value).clone();
            match value_data.kind() {
                ValueKind::Integer(integer) => {
                    codes.push(format!("  li\t{}, {}", REGISTER_NAMES[reg], integer.value()))
                }
                ValueKind::GlobalAlloc(_) => {
                    let name = value_data.name().as_ref().unwrap()[1..].to_string();
                    codes.extend(self.load_global(reg, name));
                }
                _ => {}
            }
            return codes;
        }
        let value_data = self.fd.dfg().value(value).clone();
        match value_data.kind() {
            ValueKind::Integer(integer) => {
                codes.push(format!("  li\t{}, {}", REGISTER_NAMES[reg], integer.value()))
            }
            ValueKind::ZeroInit(_) | ValueKind::Undef(_) => {
                codes.push(format!("  li\t{}, 0", REGISTER_NAMES[reg]))
            }
            _ => {
                // Prefer the value's stack slot: every local value (including
                // spilled instruction results and saved arguments) has one.
                if let Some(&offset) = self.local_value_location.get(&value) {
                    codes.extend(self.load_with_offset(reg, offset as isize));
                } else if let ValueKind::FuncArgRef(arg) = value_data.kind() {
                    // Fallback, only valid at function entry.
                    if arg.index() < REGISTER_FOR_ARGS.len() {
                        codes.push(format!(
                            "  mv\t{}, {}",
                            REGISTER_NAMES[reg], REGISTER_NAMES[REGISTER_FOR_ARGS[arg.index()]]
                        ));
                    }
                }
            }
        }
        codes
    }

    /// Want to visit a value. Make it appear in a register.
    fn want_to_visit_value(
        &mut self,
        value: Value,
        do_load: bool,
        use_certain_reg: Option<usize>,
    ) -> (usize, Vec<String>) {
        let mut codes = Vec::new();
        let reg = match use_certain_reg {
            Some(certain_reg) => {
                match self.__is_value_in_register(value) {
                    Some(src) if src == certain_reg => {
                        self.__update_user(certain_reg, value);
                        return (certain_reg, codes);
                    }
                    Some(src) => {
                        codes.extend(self.save_register(certain_reg));
                        codes.push(format!(
                            "  mv\t{}, {}",
                            REGISTER_NAMES[certain_reg], REGISTER_NAMES[src]
                        ));
                    }
                    None => {
                        codes.extend(self.save_register(certain_reg));
                        if do_load {
                            codes.extend(self.__load_value(value, certain_reg));
                        }
                    }
                }
                certain_reg
            }
            None => match self.__is_value_in_register(value) {
                Some(reg) => {
                    self.__update_user(reg, value);
                    return (reg, codes);
                }
                None => {
                    let (reg, alloc_codes) = self.get_tmp_reg();
                    codes.extend(alloc_codes);
                    if do_load {
                        codes.extend(self.__load_value(value, reg));
                    }
                    reg
                }
            },
        };
        self.__update_user(reg, value);
        (reg, codes)
    }

    /// Makes the register holding v1 also serve v2 (both have the same content).
    #[allow(dead_code)]
    fn assign_v1_to_v2(&mut self, v1: Value, v2: Value) -> Vec<String> {
        let (reg, codes) = self.want_to_visit_value(v1, true, None);
        self.__update_user(reg, v2);
        codes
    }

    /// Example:
    /// getelemptr @a, 114 -> The absolute location of @a in memory.
    /// getelemptr %0, 514 -> The value of %0 (which is an address).
    fn get_absolute_location(&mut self, value: Value) -> (usize, Vec<String>) {
        let mut codes = Vec::new();
        let value_data = self.fd.dfg().value(value).clone();
        let (base, index) = match value_data.kind() {
            ValueKind::GetElemPtr(get_elem_ptr) => (get_elem_ptr.src(), get_elem_ptr.index()),
            ValueKind::GetPtr(get_ptr) => (get_ptr.src(), get_ptr.index()),
            _ => panic!("get_absolute_location expects a getelemptr/getptr value! "),
        };
        // The result type is *T, so one index step is sizeof(T) bytes.
        let elem_size = match value_data.ty().kind() {
            TypeKind::Pointer(base_ty) => base_ty.size(),
            _ => 4,
        };
        // Visit the index first: its fresh timestamp protects it from being
        // evicted while the base register is allocated below.
        let (index_reg, index_codes) = self.want_to_visit_value(index, true, None);
        codes.extend(index_codes);
        codes.push(format!("  li\t{}, {}", REGISTER_NAMES[REG_X31], elem_size));
        codes.push(format!(
            "  mul\t{}, {}, {}",
            REGISTER_NAMES[index_reg], REGISTER_NAMES[index_reg], REGISTER_NAMES[REG_X31]
        ));
        let base_data = match base.is_global() {
            true => self.program.borrow_value(base).clone(),
            false => self.fd.dfg().value(base).clone(),
        };
        let base_reg = match base_data.kind() {
            ValueKind::GlobalAlloc(_) => {
                let (reg, base_codes) = self.get_tmp_reg();
                codes.extend(base_codes);
                let name = base_data.name().as_ref().unwrap()[1..].to_string();
                codes.push(format!("  la\t{}, {}", REGISTER_NAMES[reg], name));
                reg
            }
            ValueKind::Alloc(_) => {
                let (reg, base_codes) = self.get_tmp_reg();
                codes.extend(base_codes);
                let offset = *self
                    .local_value_location
                    .get(&base)
                    .expect("Local alloc must own a stack slot! ");
                codes.extend(self.add_with_offset(reg, offset as isize));
                reg
            }
            _ => {
                // The base is a pointer produced by another instruction
                // (load / getelemptr / getptr / call / argument).
                let (reg, base_codes) = self.want_to_visit_value(base, true, None);
                codes.extend(base_codes);
                reg
            }
        };
        codes.push(format!(
            "  add\t{}, {}, {}",
            REGISTER_NAMES[base_reg], REGISTER_NAMES[base_reg], REGISTER_NAMES[index_reg]
        ));
        if index_reg != base_reg {
            self.__free_user(index_reg);
        }
        (base_reg, codes)
    }
}

